--!strict
-- Records the collision and trigger callbacks its entity receives, for the PhysicsSemantics suite and replay
-- (Docs/Decisions/0031-m20-contract.md decisions 2 and 3): each with the names of the entities involved and the tick it
-- arrived on, in the instance's own list and in one log that every probe of the scene's VM shares, in arrival order.

export type Event = {
	Kind: string,
	Self: string,
	Other: string,
	Collider: string,
	OtherCollider: string,
	Tick: number,
}

export type ColliderProbe = ScriptInstance & {
	Events: { Event },
	Log: { Event },
}

local Log: { Event } = {}

local ColliderProbe = {}

local function Record(self: ColliderProbe, kind: string, other: Entity, contact: CollisionContact?)
	local event: Event = {
		Kind = kind,
		Self = self.Entity.Name,
		Other = other.Name,
		Collider = if contact then contact.Collider.Name else "",
		OtherCollider = if contact then contact.OtherCollider.Name else "",
		Tick = Time.GetTick(),
	}
	table.insert(self.Events, event)
	table.insert(Log, event)
end

function ColliderProbe.OnCreate(self: ColliderProbe)
	self.Events = {}
	self.Log = Log
end

function ColliderProbe.OnCollisionEnter(self: ColliderProbe, other: Entity, contact: CollisionContact)
	Record(self, "CollisionEnter", other, contact)
end

function ColliderProbe.OnCollisionExit(self: ColliderProbe, other: Entity)
	Record(self, "CollisionExit", other, nil)
end

function ColliderProbe.OnTriggerEnter(self: ColliderProbe, other: Entity)
	Record(self, "TriggerEnter", other, nil)
end

function ColliderProbe.OnTriggerExit(self: ColliderProbe, other: Entity)
	Record(self, "TriggerExit", other, nil)
end

return Script.Define("ColliderProbe", ColliderProbe)

--!strict
-- The collision form of the read rule (Docs/Decisions/0031-m20-contract.md decision 4): Anvil and Hammer both run it.
-- A pair's enter reaches the entity with the lower id first, which destroys itself; the other one's callback, later in the
-- same dispatch, then reads the destroyed partner, which stays readable until the end-of-step flush.

export type Reading = { Ok: boolean, Name: string, Height: number, Valid: boolean, Tick: number }

export type Crusher = ScriptInstance & {
	Partner: string,
	Read: Reading?,
}

local Crusher = {}

Crusher.Fields = {
	Partner = Field.String("", { Tooltip = "The name of the entity this one crushes or is crushed by" }),
}

function Crusher.OnCollisionEnter(self: Crusher, other: Entity, _contact: CollisionContact)
	if other.Name ~= self.Partner or self.Read ~= nil then
		return
	end
	if self.Entity.ID < other.ID then
		Scene.Destroy(self.Entity)
		return
	end
	local ok, name, height = pcall(function(): (string, number)
		return other.Name, other.Transform.WorldPosition.y
	end)
	self.Read = {
		Ok = ok,
		Name = if ok then name else "",
		Height = if ok then height else 0,
		Valid = other:IsValid(),
		Tick = Time.GetTick(),
	}
end

return Script.Define("Crusher", Crusher)
